package com.agenda.clinica.config;
import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig { @Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService users(org.springframework.core.env.Environment env,PasswordEncoder e){String u=env.getProperty("APP_ADMIN_USER","admin");String p=env.getProperty("APP_ADMIN_PASSWORD","CambiarAdmin2026!");return new InMemoryUserDetailsManager(User.withUsername(u).password(e.encode(p)).roles("ADMIN").build());} @Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).authorizeHttpRequests(a->a.requestMatchers("/api/public/**","/error").permitAll().requestMatchers(org.springframework.http.HttpMethod.OPTIONS,"/**").permitAll().anyRequest().hasRole("ADMIN")).httpBasic(Customizer.withDefaults()).build();} }
